import {platforms,otherIntegrations,SOURCES,validatePost} from './platforms.js';
import {all,get,put,remove} from './storage.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let posts=[],media=[],page='planner',month=new Date(),calendarMode='month',editing=null,targets=[],selectedMedia=[],urls=[];
const tz=Intl.DateTimeFormat().resolvedOptions().timeZone;
const icon=p=>`<span class="platform-icon" style="--color:${p.color}">${esc(p.mark)}</span>`;
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const localDate=d=>`${dateKey(d)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
const readable=d=>new Date(d).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function fail(error){console.error(error);toast('Could not save this change. Check available device storage and try again.');}
async function refresh(){posts=await all('posts');media=await all('media');$('#draft-count').textContent=posts.filter(p=>p.status==='draft').length;render();}
function header(title,description,action=true){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${action?'<button class="button primary" data-action="create"><span>＋</span> Create post</button>':''}</div>`;}
function render(){
 urls.forEach(URL.revokeObjectURL);urls=[];
 page=location.hash.slice(1)||'planner';if(!['planner','drafts','library','channels','roadmap'].includes(page))page='planner';
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));
 $('#breadcrumb').textContent={planner:'Content planner',drafts:'Drafts',library:'Media library',channels:'Channels & formats',roadmap:'Build roadmap'}[page];
 if(page==='planner')renderPlanner();if(page==='drafts')renderDrafts();if(page==='library')renderLibrary();if(page==='channels')renderChannels();if(page==='roadmap')renderRoadmap();
}
function renderPlanner(){
 const planned=posts.filter(p=>p.status==='planned');
 $('#view').innerHTML=header('Your content, in good company.','A little planning. A lot of possibility.')+`<section class="hero"><div><div class="eyebrow">ONE WORKSPACE. EVERY CHANNEL.</div><h2>Good stories deserve<br>to be seen everywhere.</h2><p>Turn your next idea into a post, tailor it to each platform,<br>and give your content a place on the calendar.</p></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="art-square">e</div><span class="float one">◎</span><span class="float two">in</span><span class="spark">✳</span></div></section><section class="stats" aria-label="Workspace totals">${[['Planned posts',planned.length,'Your next stories, lined up','▦'],['Drafts',posts.filter(p=>p.status==='draft').length,'Ideas taking shape','▤'],['Publishing channels',10,'Formats ready to explore','◉'],['Connected accounts',0,'Connectors coming next','↗']].map(([label,n,detail,symbol])=>`<div class="stat"><div class="stat-label">${label}<span class="stat-symbol">${symbol}</span></div><strong>${n}</strong><small>${detail}</small></div>`).join('')}</section><section class="calendar-panel"><div class="calendar-toolbar"><div class="calendar-controls"><h2>${month.toLocaleString(undefined,{month:'long',year:'numeric'})}</h2><button class="icon-button" data-action="previous" aria-label="Previous month">‹</button><button class="icon-button" data-action="next" aria-label="Next month">›</button><button class="today-button" data-action="today">Today</button></div><div class="calendar-controls"><div class="segmented"><button data-action="month" class="${calendarMode==='month'?'active':''}">Month</button><button data-action="list" class="${calendarMode==='list'?'active':''}">List</button></div></div></div>${calendarMode==='month'?calendar():planned.length?`<div class="post-list" style="padding:15px">${planned.sort((a,b)=>a.plannedAt.localeCompare(b.plannedAt)).map(postRow).join('')}</div>`:'<div class="empty"><div class="empty-symbol">▦</div><h2>A fresh page for your next idea.</h2><p>Create a post and choose a date to see it here.</p><button class="button primary" data-action="create">Plan your first post ↗</button></div>'}<div class="legend"><div><span><i></i> Planned</span><span><i class="sand"></i> Draft</span></div><span>${esc(tz)} · Local planning</span></div></section><div class="source-note">Your calendar is ready. Automatic publishing will become available as authorized platform connections are added. <a href="#channels">Explore channels & formats ↗</a></div>`;
}
function calendar(){
 const first=new Date(month.getFullYear(),month.getMonth(),1),start=new Date(first);start.setDate(1-(first.getDay()+6)%7);
 const weeks=Math.ceil(((first.getDay()+6)%7+new Date(month.getFullYear(),month.getMonth()+1,0).getDate())/7);
 const today=dateKey(new Date());let cells='';
 for(let i=0;i<weeks*7;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=dateKey(d);const matches=posts.filter(p=>p.plannedAt&&dateKey(new Date(p.plannedAt))===key);cells+=`<div class="calendar-day ${d.getMonth()!==month.getMonth()?'outside':''} ${key===today?'today':''}"><span class="day-label">${d.getDate()}</span><button class="add-day" data-date="${key}" aria-label="Create post for ${key}">+</button>${matches.slice(0,3).map(p=>`<button class="post-chip ${p.status==='draft'?'draft':''}" data-edit="${esc(p.id)}" title="${esc(p.caption)}">${esc(platforms.find(n=>n.id===p.targets[0]?.id)?.mark||'•')} ${esc(p.caption||p.title||'Media post')}</button>`).join('')}${matches.length>3?`<button class="text-button" data-day="${key}" style="font-size:8px">+${matches.length-3} more</button>`:''}</div>`;}
 return `<div class="calendar-weekdays">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${cells}</div>`;
}
function postRow(p){return `<article class="post-row"><div>${icon(platforms.find(n=>n.id===p.targets[0]?.id)||platforms[0])}</div><div class="post-summary"><h3>${esc(p.caption||p.title||'Untitled draft')}</h3><p>${p.targets.map(t=>esc(platforms.find(n=>n.id===t.id)?.name||'')).join(' · ')}${p.plannedAt?' &nbsp; / &nbsp; '+esc(readable(p.plannedAt)):''} &nbsp; <span class="tag">${p.status==='planned'?'Planned':'Draft'}</span></p></div><button class="button secondary" data-edit="${esc(p.id)}">Edit</button><button class="icon-button" data-duplicate="${esc(p.id)}" aria-label="Duplicate post">⧉</button><button class="icon-button" data-delete="${esc(p.id)}" aria-label="Delete post">×</button></article>`;}
function renderDrafts(){const drafts=posts.filter(p=>p.status==='draft');$('#view').innerHTML=header('Ideas start here.','A home for the posts you’re still making your own.')+(drafts.length?`<div class="post-list">${drafts.map(postRow).join('')}</div>`:`<div class="empty"><div class="empty-symbol">✎</div><h2>Make room for a little inspiration.</h2><p>Save an unfinished caption, collect an idea or start your next campaign. Your drafts will be waiting here.</p><button class="button primary" data-action="create">Create a draft ↗</button></div>`);}
function mediaURL(m){const url=URL.createObjectURL(m.blob);urls.push(url);return url;}
function mediaVisual(m){return m.type.startsWith('image/')?`<img src="${mediaURL(m)}" alt="${esc(m.name)}" loading="lazy">`:m.type.startsWith('video/')?`<video src="${mediaURL(m)}" preload="metadata" controls></video>`:`<div class="file-tile">▤</div>`;}
function renderLibrary(){ $('#view').innerHTML=header('A library of possibilities.','Your images, videos and documents, ready for their next story.',false)+`<div class="view-tools" style="margin-bottom:20px"><button class="button primary" data-action="upload">＋ Upload media</button><input class="search" id="media-search" aria-label="Search media" placeholder="Search your library…"><span class="source-note">${media.length} assets · Device storage</span></div><input type="file" id="library-upload" multiple accept="image/*,video/*,.pdf,.ppt,.pptx,.doc,.docx" hidden><div class="library-grid" id="media-grid">${media.map(m=>`<article class="media-card" data-name="${esc(m.name.toLowerCase())}">${mediaVisual(m)}<div class="media-card-info"><strong>${esc(m.name)}</strong><small>${(m.size/1024/1024).toFixed(1)} MB${m.width?' · '+m.width+' × '+m.height:''}</small><button class="text-button" data-remove-media="${esc(m.id)}">Remove</button></div></article>`).join('')}</div>${!media.length?'<div class="empty"><div class="empty-symbol">▧</div><h2>Give your ideas a visual home.</h2><p>Upload your first photo, video or document. Files stay on this device until you export your workspace.</p></div>':''}`;}
function renderChannels(){ $('#view').innerHTML=header('Every channel. Its own voice.','Explore the posting formats we’re building into Elleson Socials.',false)+`<div class="notice">10 publishing networks, plus Twitch, advertising and website analytics in the integration scope. Account connections are not configured in this preview. The cards below describe the publishing baseline, not active integrations.</div><div class="platform-grid">${platforms.map(p=>`<article class="platform-card"><div class="platform-top">${icon(p)}<div><h3>${p.name}</h3><small>${p.limit.toLocaleString()} caption characters · Setup required</small></div></div><p>${esc(p.tip)}</p><div class="format-tags">${p.formats.map(f=>`<span class="tag">${f}</span>`).join('')}</div><button class="text-button" data-compose-channel="${p.id}">Create a ${p.name} draft ↗</button></article>`).join('')}</div><h2 class="section-title">Beyond publishing</h2><div class="platform-grid">${otherIntegrations.map(p=>`<article class="platform-card"><div class="platform-top">${icon(p)}<div><h3>${p.name}</h3><small>${p.kind} · Planned integration</small></div></div><p>${p.detail}</p></article>`).join('')}</div><p class="source-note">Research baseline: 2 November 2026. <a href="${SOURCES.formats}" target="_blank" rel="noopener">Metricool posting formats ↗</a> · <a href="${SOURCES.media}" target="_blank" rel="noopener">Media requirements ↗</a><br>Native app features and third-party API features differ. Limits must be checked again against each authorized account before live publication.</p>`;}
function renderRoadmap(){ $('#view').innerHTML=header('A clear path to publishing.','Web and Android, built around the same content workflow.',false)+`<div class="roadmap"><article><span class="status-tag">AVAILABLE IN THIS PREVIEW</span><h2>Your planning workspace</h2><ul><li>Calendar, drafts, editing and duplication</li><li>Ten platform choices with individual formats and captions</li><li>Media library and basic content checks</li><li>Local persistence and portable workspace backups</li><li>Responsive interface shared with the Android project</li></ul></article><article><span class="status-tag pending">NEXT · SERVER & IDENTITY</span><h2>One workspace across devices</h2><ul><li>Sign-in, brands and team permissions</li><li>Server database and private media storage</li><li>Secure platform authorization and token refresh</li><li>Synchronization between web and Android</li></ul></article><article><span class="status-tag pending">REQUIRES PROVIDER ACCESS</span><h2>Real publishing</h2><ul><li>Platform developer registrations and approvals</li><li>Persistent scheduled jobs and account capability checks</li><li>Upload processing, retries and duplicate prevention</li><li>Publication receipts and actionable failure messages</li><li>Phone reminders for formats that need manual completion</li></ul></article><article><span class="status-tag pending">FOLLOWING MILESTONES</span><h2>Measure, learn, grow</h2><ul><li>Analytics, best times and branded reports</li><li>Supported comments and message inboxes</li><li>Approval workflows and evergreen queues</li><li>Twitch, ad reporting, website analytics and link-in-bio</li><li>Android notifications, sharing and release signing</li></ul></article></div><div class="notice">Nothing in this preview sends content to social networks. Planning dates are saved locally; they do not create a server job or a phone notification.</div>`;}
function showErrors(errors){$('#form-errors').hidden=!errors.length;$('#form-errors').innerHTML=errors.map(e=>`<div>• ${esc(e)}</div>`).join('');if(errors.length)$('#form-errors').scrollIntoView({block:'nearest',behavior:'smooth'});}
function openComposer(id=null,date=null,channel=null){
 const post=posts.find(p=>p.id===id);editing=post?.id||null;targets=structuredClone(post?.targets||[]);selectedMedia=[...(post?.mediaIds||[])];if(channel)targets=[{id:channel,format:platforms.find(p=>p.id===channel).formats[0]}];
 $('#composer-title').textContent=post?'Edit your post':'Create a post';$('#caption').value=post?.caption||'';$('#post-title').value=post?.title||'';$('#post-board').value=post?.board||'';
 $('#planned-at').value=post?.plannedAt?localDate(new Date(post.plannedAt)):date?date+'T09:00':'';$('#timezone').textContent=tz;$('#library-picker').hidden=true;showErrors([]);drawTargets();drawMedia();updatePreview();$('#composer').showModal();
}
function drawTargets(){
 $('#channel-picker').innerHTML=platforms.map(p=>`<button type="button" data-toggle-channel="${p.id}" class="${targets.some(t=>t.id===p.id)?'selected':''}" title="${esc(p.name)}" aria-label="${esc(p.name)}" aria-pressed="${targets.some(t=>t.id===p.id)}">${icon(p)}</button>`).join('');
 $('#variants').innerHTML=targets.map(t=>{const p=platforms.find(p=>p.id===t.id);return `<section class="variant"><div class="variant-head">${icon(p)} ${p.name}<select data-format="${p.id}" aria-label="${p.name} post format">${p.formats.map(f=>`<option ${t.format===f?'selected':''}>${f}</option>`).join('')}</select></div><textarea rows="2" data-caption="${p.id}" aria-label="Caption for ${p.name}" placeholder="Use the shared caption, or write one just for ${p.name}">${esc(t.caption??'')}</textarea><small>${p.limit.toLocaleString()} characters maximum · ${esc(p.tip)}</small></section>`;}).join('');
}
function drawMedia(){const list=selectedMedia.map(id=>media.find(m=>m.id===id)).filter(Boolean);$('#composer-media').innerHTML=list.map(m=>`<div class="media-thumb">${mediaVisual(m)}<button type="button" data-detach="${m.id}" aria-label="Remove ${esc(m.name)} from post">×</button><small>${esc(m.name)}</small></div>`).join('');}
function updatePreview(){const text=$('#caption').value;$('#character-count').textContent=`${[...text].length.toLocaleString()} characters`;$('#preview-caption').textContent=text||'Your story starts here.';const item=media.find(m=>m.id===selectedMedia[0]);$('#preview-media').innerHTML=item?mediaVisual(item):'<span>YOUR NEXT<br>GREAT IDEA.</span><i>✳</i>';}
function collectPost(status){return {id:editing||crypto.randomUUID(),caption:$('#caption').value,title:$('#post-title').value,board:$('#post-board').value,targets:structuredClone(targets),mediaIds:[...selectedMedia],plannedAt:$('#planned-at').value?new Date($('#planned-at').value).toISOString():null,timezone:tz,status,updatedAt:new Date().toISOString()};}
async function savePost(status){
 const post=collectPost(status);const attached=selectedMedia.map(id=>media.find(m=>m.id===id)).filter(Boolean);let errors=[];
 if(status==='planned'){errors=validatePost(post,attached);if(!post.plannedAt)errors.push('Choose a planned date and time.');else if(new Date(post.plannedAt)<=new Date())errors.push('Choose a future date and time.');}
 else if(!post.caption.trim()&&!post.title.trim()&&!attached.length){errors.push('Add a caption, title or media to save a draft.');}
 if(errors.length){showErrors(errors);return;}await put('posts',post);$('#composer').close();await refresh();toast(status==='draft'?'Draft saved. Your idea is in good hands.':'Added to your plan. Live publishing is not connected.');
}
async function fileMeta(file){
 const result={id:crypto.randomUUID(),name:file.name,type:file.type||guessType(file.name),size:file.size,blob:file,createdAt:new Date().toISOString()};
 if(result.type.startsWith('image/')||result.type.startsWith('video/')){
  const url=URL.createObjectURL(file);try{await new Promise(resolve=>{const el=document.createElement(result.type.startsWith('image/')?'img':'video');const timer=setTimeout(resolve,4000);el.onload=el.onloadedmetadata=()=>{result.width=el.naturalWidth||el.videoWidth;result.height=el.naturalHeight||el.videoHeight;if(el.duration&&isFinite(el.duration))result.duration=el.duration;clearTimeout(timer);resolve();};el.onerror=()=>{clearTimeout(timer);resolve();};el.src=url;});}finally{URL.revokeObjectURL(url);}
 }return result;
}
function guessType(name){return {pdf:'application/pdf',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation'}[name.split('.').pop()?.toLowerCase()]||'application/octet-stream';}
async function upload(files,attach=false){
 for(const file of files){const ext=file.name.split('.').pop().toLowerCase();if(!(file.type.startsWith('image/')||file.type.startsWith('video/')||['pdf','ppt','pptx','doc','docx'].includes(ext))){toast(`Unsupported file: ${file.name}`);continue;}if(file.size>500*1024*1024){toast(`${file.name} exceeds this preview’s 500 MB upload limit.`);continue;}const item=await fileMeta(file);await put('media',item);if(attach)selectedMedia.push(item.id);}
 media=await all('media');if(attach){drawMedia();updatePreview();}else render();toast('Media saved on this device.');
}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function exportWorkspace(){
 toast('Preparing your workspace backup…');const assets=[];for(const item of media){const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(item.blob);});const {blob,...meta}=item;assets.push({...meta,data});}
 download(JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),posts,media:assets}),`elleson-socials-${dateKey(new Date())}.json`);toast('Workspace exported, including your media.');
}
async function importWorkspace(file){
 if(!file)return;const backup=JSON.parse(await file.text());
 if(backup.schemaVersion!==1||!Array.isArray(backup.posts)||!Array.isArray(backup.media))throw Error('Invalid backup');
 // Validate the complete backup before beginning a merge. Existing records are kept.
 const importedMedia=[];for(const m of backup.media){if(typeof m.id!=='string'||typeof m.name!=='string'||typeof m.type!=='string'||!/^data:[^,]*;base64,/.test(m.data))throw Error('Invalid media');const blob=await (await fetch(m.data)).blob();const {data,...meta}=m;importedMedia.push({...meta,blob});}
 for(const p of backup.posts){if(typeof p.id!=='string'||typeof p.caption!=='string'||!['draft','planned'].includes(p.status)||!Array.isArray(p.targets)||!Array.isArray(p.mediaIds)||p.targets.some(t=>!platforms.some(n=>n.id===t.id&&n.formats.includes(t.format)))||p.plannedAt&&!Number.isFinite(Date.parse(p.plannedAt)))throw Error('Invalid post');}
 for(const m of importedMedia)if(!media.some(x=>x.id===m.id))await put('media',m);
 for(const p of backup.posts)if(!posts.some(x=>x.id===p.id))await put('posts',p);
 await refresh();toast('Backup imported. Existing posts and media were kept.');
}
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
 const d=button.dataset;
 if(d.action==='create')openComposer();if(d.date)openComposer(null,d.date);if(d.composeChannel)openComposer(null,null,d.composeChannel);if(d.edit)openComposer(d.edit);
 if(d.action==='previous'||d.action==='next'){month=new Date(month.getFullYear(),month.getMonth()+(d.action==='next'?1:-1),1);render();}
 if(d.action==='today'){month=new Date();render();}if(d.action==='month'||d.action==='list'){calendarMode=d.action;render();}if(d.day){calendarMode='list';render();}
 if(d.action==='upload')$('#library-upload').click();
 if(d.toggleChannel){const existing=targets.find(t=>t.id===d.toggleChannel);targets=existing?targets.filter(t=>t.id!==d.toggleChannel):[...targets,{id:d.toggleChannel,format:platforms.find(p=>p.id===d.toggleChannel).formats[0]}];drawTargets();}
 if(d.detach){selectedMedia=selectedMedia.filter(id=>id!==d.detach);drawMedia();updatePreview();}
 if(d.attach){if(!selectedMedia.includes(d.attach))selectedMedia.push(d.attach);drawMedia();updatePreview();}
 if(d.duplicate){const p=structuredClone(posts.find(p=>p.id===d.duplicate));p.id=crypto.randomUUID();p.status='draft';p.plannedAt=null;p.updatedAt=new Date().toISOString();await put('posts',p);await refresh();toast('Copied to drafts.');}
 if(d.delete&&confirm('Delete this post from your workspace?')){await remove('posts',d.delete);await refresh();toast('Post deleted.');}
 if(d.removeMedia){if(posts.some(p=>p.mediaIds.includes(d.removeMedia))){toast('This file is attached to a post. Remove it from those posts first.');return;}if(confirm('Remove this media from the device library?')){await remove('media',d.removeMedia);await refresh();}}
 }catch(error){fail(error);}});
document.addEventListener('input',event=>{if(event.target.id==='caption')updatePreview();if(event.target.dataset.caption){const t=targets.find(t=>t.id===event.target.dataset.caption);const value=event.target.value;if(value.trim())t.caption=value;else delete t.caption;}if(event.target.id==='media-search'){const query=event.target.value.toLowerCase();document.querySelectorAll('.media-card').forEach(el=>el.hidden=!el.dataset.name.includes(query));}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.format)targets.find(t=>t.id===el.dataset.format).format=el.value;if(el.id==='library-upload')upload([...el.files]).catch(fail);if(el.id==='post-upload'){upload([...el.files],true).catch(fail);el.value='';}});
$('#close-composer').onclick=()=>$('#composer').close();$('#post-form').onsubmit=e=>{e.preventDefault();savePost('planned').catch(fail);};$('#save-draft').onclick=()=>savePost('draft').catch(fail);
$('#choose-library').onclick=()=>{const picker=$('#library-picker');picker.hidden=!picker.hidden;picker.innerHTML=media.length?media.map(m=>`<button class="library-choice" type="button" data-attach="${m.id}">＋ ${esc(m.name)}</button>`).join(''):'<p class="source-note">Your library is empty. Upload a file above.</p>';};
$('#export').onclick=()=>exportWorkspace().catch(fail);$('#import').onchange=e=>{importWorkspace(e.target.files[0]).catch(()=>toast('This backup could not be imported. Choose an Elleson Socials workspace export.'));e.target.value='';};
window.addEventListener('hashchange',render);
refresh().catch(fail);
